"use client";
import { useEffect, useState } from "react";
import Link from "next/link";

export default function Nav() {
    const [user, setUser] = useState(null);

    useEffect(() => {
        const fetchUser = async () => {
            try {
                const res = await fetch("/api/auth/me");
                if (!res.ok) throw new Error("Not authenticated");
                const data = await res.json();
                setUser(data);
            } catch (error) {
                setUser(null);
            }
        };

        fetchUser();
    }, []);

    return (
        <nav className="bg-gray-800">
            <div className="container mx-auto px-6 py-3">
                <div className="flex items-center justify-between">
                    <div className="w-full text-white flex items-center">
                        <Link href="/" className="text-sm font-semibold text-white hover:text-gray-200">Home</Link>
                        <Link href="/content-page" className="text-sm font-semibold text-white hover:text-gray-200 ml-8">Content</Link>
                        <Link href="/resource" className="text-sm font-semibold text-white hover:text-gray-200 ml-8">Resource</Link>

                        {user ? (
                            <>
                                {user.role === "admin" && (
                                    <Link href="/admin" className="text-sm font-semibold text-white hover:text-gray-200 ml-8">Admin</Link>
                                )}
                                <span className="ml-8 text-amber-100">Welcome, {user.name}</span>
                            </>
                        ) : (
                            <>
                                <Link href="/login" className="text-sm font-semibold text-white hover:text-gray-200 ml-8">Login</Link>
                                <Link href="/signup" className="text-sm font-semibold text-white hover:text-gray-200 ml-8">Register</Link>
                            </>
                        )}
                    </div>
                </div>
            </div>
        </nav>
    );
}
